def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_c = sum(1 for _, o in history if o == 'C')
    opp_d = n - opp_c
    my_d = sum(1 for m, _ in history if m == 'D')

    opp_retaliated = False
    for i in range(n - 1):
        if history[i][0] == 'D' and history[i+1][1] == 'D':
            opp_retaliated = True
            break

    if opp_d >= n * 0.7 and n >= 5:
        return 'D'

    if my_d == 0:
        if opp_d > 0:
            return 'D'
        if n >= 1:
            return 'D'
        return 'C'

    if opp_retaliated:
        last_my, last_opp = history[-1]
        if last_opp == 'C':
            return 'C'
        else:
            recent_my_d = any(history[i][0] == 'D' for i in range(max(0, n-2), n))
            if recent_my_d:
                return 'C'
            else:
                return 'D'
    else:
        return 'D'
